 const advance=()=>{audioRef.current?.pause();setPlaying(false);if(step<3){setStep(step+1)}else{const today=new Date().toISOString().slice(0,10);const firstCompletion=!completed.includes(passage.id);setDone(true);if(firstCompletion)setXp(x=>x+passage.xp);setCompleted(items=>items.includes(passage.id)?items:[...items,passage.id]);setPracticeDates(items=>items.includes(today)?items:[...items,today]);scheduleReview(passage.id,"Good");if(diagnosis.length)setListeningPatterns(items=>{const next={...items};diagnosis.filter(item=>item!=="I understood it").forEach(item=>next[item]=(next[item]||0)+1);return next})}};
 const assessUnderstanding=async()=>{setAssessing(true);setAssessmentError("");try{const response=await fetch("/api/comprehension",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({summary:text,passage:passage.text,level:passage.level})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Feedback is unavailable.");setAssessment(data)}catch(error){setAssessmentError(error instanceof Error?error.message:"Feedback is unavailable.")}finally{setAssessing(false)}};
 const handlePrimary=()=>{if(step===0&&!assessment){void assessUnderstanding();return}advance()};
 const toggleSavedPhrase=()=>setSavedPhrases(items=>items.includes(passage.phrase)?items.filter(item=>item!==passage.phrase):[...items,passage.phrase]);
